package com.example.ancapp.data

import android.content.Context
import android.util.Log
import dev.ohs.fhir.engine.FhirEngine
import dev.ohs.fhir.engine.FhirEngineProvider
import dev.ohs.fhir.engine.db.impl.deserializeResource
import dev.ohs.fhir.engine.db.impl.serializeResource
import dev.ohs.fhir.engine.search.search
import dev.ohs.fhir.engine.sync.AcceptRemoteConflictResolver
import dev.ohs.fhir.model.r4.Encounter
import dev.ohs.fhir.model.r4.Observation
import dev.ohs.fhir.model.r4.Patient
import dev.ohs.fhir.model.r4.Questionnaire
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import dev.ohs.fhir.model.r4.Resource
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL
import java.time.LocalDate
import java.time.Period
import java.time.temporal.ChronoUnit
import java.util.UUID

class AncRepository(private val context: Context) {
  private val fhirEngine: FhirEngine by lazy {
    FhirEngineProvider.getInstance(context)
  }

  private val serverBaseUrl = "http://10.0.2.2:8080/fhir"

  @Volatile
  private var cachedQuestionnaireJson: String? = null

  suspend fun syncWithServer() = withContext(Dispatchers.IO) {
    try {
      // 1. Download Questionnaire
      val qJson = fetchUrl("$serverBaseUrl/Questionnaire/anc-contact")
      if (qJson != null) {
        cachedQuestionnaireJson = qJson
        val qRes = deserializeResource(qJson)
        fhirEngine.syncDownload(AcceptRemoteConflictResolver) {
          flow { emit(listOf(qRes)) }
        }
      }
    } catch (e: Exception) {
      Log.e("AncRepository", "Failed to sync Questionnaire", e)
    }

    try {
      // 2. Download Patients
      val patientsBundleJson = fetchUrl("$serverBaseUrl/Patient")
      if (patientsBundleJson != null) {
        val patientResources = parseBundle(patientsBundleJson)
        if (patientResources.isNotEmpty()) {
          fhirEngine.syncDownload(AcceptRemoteConflictResolver) {
            flow { emit(patientResources) }
          }
        }
      }
    } catch (e: Exception) {
      Log.e("AncRepository", "Failed to sync Patients", e)
    }

    try {
      // 3. Download Encounters
      val encountersBundleJson = fetchUrl("$serverBaseUrl/Encounter")
      if (encountersBundleJson != null) {
        val encounterResources = parseBundle(encountersBundleJson)
        if (encounterResources.isNotEmpty()) {
          fhirEngine.syncDownload(AcceptRemoteConflictResolver) {
            flow { emit(encounterResources) }
          }
        }
      }
    } catch (e: Exception) {
      Log.e("AncRepository", "Failed to sync Encounters", e)
    }

    try {
      // 4. Download Observations
      val observationsBundleJson = fetchUrl("$serverBaseUrl/Observation")
      if (observationsBundleJson != null) {
        val observationResources = parseBundle(observationsBundleJson)
        if (observationResources.isNotEmpty()) {
          fhirEngine.syncDownload(AcceptRemoteConflictResolver) {
            flow { emit(observationResources) }
          }
        }
      }
    } catch (e: Exception) {
      Log.e("AncRepository", "Failed to sync Observations", e)
    }

    try {
      // 5. Download QuestionnaireResponses if any
      val qrBundleJson = fetchUrl("$serverBaseUrl/QuestionnaireResponse")
      if (qrBundleJson != null) {
        val qrResources = parseBundle(qrBundleJson)
        if (qrResources.isNotEmpty()) {
          fhirEngine.syncDownload(AcceptRemoteConflictResolver) {
            flow { emit(qrResources) }
          }
        }
      }
    } catch (e: Exception) {
      Log.e("AncRepository", "Failed to sync QuestionnaireResponses", e)
    }
  }

  suspend fun getQuestionnaireJson(): String = withContext(Dispatchers.IO) {
    cachedQuestionnaireJson?.let { return@withContext it }
    try {
      val q = fhirEngine.search<Questionnaire> {}.map { it.resource }.firstOrNull { it.id == "anc-contact" }
      if (q != null) {
        val serialized = serializeResource(q)
        cachedQuestionnaireJson = serialized
        return@withContext serialized
      }
    } catch (e: Exception) {
      Log.w("AncRepository", "Could not load questionnaire from local db", e)
    }

    try {
      val remoteJson = fetchUrl("$serverBaseUrl/Questionnaire/anc-contact")
      if (remoteJson != null) {
        cachedQuestionnaireJson = remoteJson
        return@withContext remoteJson
      }
    } catch (e: Exception) {
      Log.w("AncRepository", "Could not load questionnaire from remote server", e)
    }

    FALLBACK_QUESTIONNAIRE_JSON
  }

  suspend fun getPatients(): List<PatientItem> = withContext(Dispatchers.IO) {
    val patientResults = fhirEngine.search<Patient> {}.map { it.resource }
    val observationResults = fhirEngine.search<Observation> {}.map { it.resource }

    val today = LocalDate.now()

    patientResults.mapNotNull { patient ->
      val pId = patient.id ?: return@mapNotNull null
      val humanName = patient.name.firstOrNull()
      val given = humanName?.given?.joinToString(" ") { it.value ?: "" } ?: ""
      val family = humanName?.family?.value ?: ""
      val fullName = "$given $family".trim()

      val birthDateStr = patient.birthDate?.value?.toString() ?: "2000-01-01"
      val birthDate = try {
        LocalDate.parse(birthDateStr)
      } catch (e: Exception) {
        LocalDate.of(2000, 1, 1)
      }
      val age = Period.between(birthDate, today).years

      // Find EDD observation (LOINC 11778-8)
      val eddObs = observationResults.firstOrNull { obs ->
        val subRef = obs.subject?.reference?.value ?: ""
        (subRef == "Patient/$pId" || subRef.endsWith(pId)) &&
            obs.code.coding.any { it.code?.value == "11778-8" }
      }

      val eddStr = eddObs?.value?.asDateTime()?.value?.toString()
        ?: eddObs?.value?.asString()?.value?.toString()
        ?: "2026-12-31"

      val eddDate = try {
        LocalDate.parse(eddStr)
      } catch (e: Exception) {
        LocalDate.of(2026, 12, 31)
      }

      // Normal pregnancy = 40 weeks = 280 days from LMP
      // Days from today to EDD:
      val daysUntilEdd = ChronoUnit.DAYS.between(today, eddDate)
      val gestationalDays = 280 - daysUntilEdd
      val weeksOfPregnancy = maxOf(0, (gestationalDays / 7).toInt())

      PatientItem(
        id = pId,
        name = fullName,
        birthDate = birthDateStr,
        age = age,
        edd = eddStr,
        weeksOfPregnancy = weeksOfPregnancy
      )
    }.sortedBy { it.edd } // Sorted by due date, soonest first
  }

  suspend fun getVisitsForPatient(patientId: String): List<AncVisitItem> = withContext(Dispatchers.IO) {
    val encounters = fhirEngine.search<Encounter> {}.map { it.resource }.filter { enc ->
      val ref = enc.subject?.reference?.value ?: ""
      ref == "Patient/$patientId" || ref.endsWith(patientId)
    }

    val observations = fhirEngine.search<Observation> {}.map { it.resource }.filter { obs ->
      val ref = obs.subject?.reference?.value ?: ""
      ref == "Patient/$patientId" || ref.endsWith(patientId)
    }

    val questionnaireResponses = fhirEngine.search<QuestionnaireResponse> {}.map { it.resource }.filter { qr ->
      val ref = qr.subject?.reference?.value ?: ""
      ref == "Patient/$patientId" || ref.endsWith(patientId)
    }

    encounters.map { enc ->
      val encId = enc.id ?: ""
      val encDate = enc.period?.start?.value?.toString() ?: ""

      // Find observations linked to this encounter (or by date matching)
      val encObs = observations.filter { obs ->
        val encRef = obs.encounter?.reference?.value ?: ""
        encRef == "Encounter/$encId" || encRef.endsWith(encId) ||
            (encRef.isEmpty() && obs.effective?.asDateTime()?.value?.toString() == encDate)
      }

      // Weight (LOINC 29463-7)
      val weightObs = encObs.firstOrNull { it.code.coding.any { c -> c.code?.value == "29463-7" } }
      val weight = weightObs?.value?.asQuantity()?.value?.value?.toString()?.toDoubleOrNull()

      // Blood pressure (LOINC 85354-9)
      val bpObs = encObs.firstOrNull { it.code.coding.any { c -> c.code?.value == "85354-9" } }
      var systolic: Int? = null
      var diastolic: Int? = null
      bpObs?.component?.forEach { comp ->
        if (comp.code.coding.any { it.code?.value == "8480-6" }) {
          systolic = comp.value?.asQuantity()?.value?.value?.toString()?.toDoubleOrNull()?.toInt()
        } else if (comp.code.coding.any { it.code?.value == "8462-4" }) {
          diastolic = comp.value?.asQuantity()?.value?.value?.toString()?.toDoubleOrNull()?.toInt()
        }
      }

      // Hemoglobin (LOINC 718-7)
      val hbObs = encObs.firstOrNull { it.code.coding.any { c -> c.code?.value == "718-7" } }
      val hb = hbObs?.value?.asQuantity()?.value?.value?.toString()?.toDoubleOrNull()

      // Gestational age (LOINC 18185-9 or 11884-4)
      val gaObs = encObs.firstOrNull { it.code.coding.any { c -> c.code?.value == "18185-9" || c.code?.value == "11884-4" } }
      val gaWeeks = gaObs?.value?.asQuantity()?.value?.value?.toString()?.toDoubleOrNull()?.toInt()

      // QuestionnaireResponse for notes & danger signs
      val qr = questionnaireResponses.firstOrNull { q ->
        val encRef = q.encounter?.reference?.value ?: ""
        encRef == "Encounter/$encId" || encRef.endsWith(encId)
      }

      var dangerSigns = emptyList<String>()
      var notes: String? = null
      if (qr != null) {
        val dangerItem = findItem(qr.item, "danger-signs")
        dangerSigns = dangerItem?.answer?.mapNotNull {
          it.value?.asCoding()?.value?.display?.value
            ?: it.value?.asCoding()?.value?.code?.value
        } ?: emptyList()

        val notesItem = findItem(qr.item, "notes")
        notes = notesItem?.answer?.firstOrNull()?.value?.asString()?.value?.value
      }

      AncVisitItem(
        encounterId = encId,
        patientId = patientId,
        date = encDate,
        weight = weight,
        systolic = systolic,
        diastolic = diastolic,
        hemoglobin = hb,
        gestationalAgeWeeks = gaWeeks,
        dangerSigns = dangerSigns,
        notes = notes
      )
    }.sortedByDescending { it.date }
  }

  suspend fun saveVisit(patientId: String, qr: QuestionnaireResponse) = withContext(Dispatchers.IO) {
    val visitDateItem = findItem(qr.item, "visit-date")
    val visitDate = visitDateItem?.answer?.firstOrNull()?.let { ans ->
      ans.value?.asDate()?.value?.toString()
        ?: ans.value?.asDateTime()?.value?.toString()
        ?: ans.value?.asString()?.value?.value
    } ?: LocalDate.now().toString()

    val gaItem = findItem(qr.item, "gestational-age")
    val gaWeeks = gaItem?.answer?.firstOrNull()?.value?.asInteger()?.value

    val weightItem = findItem(qr.item, "weight")
    val weight = weightItem?.answer?.firstOrNull()?.value?.asDecimal()?.value?.toString()?.toDoubleOrNull()

    val sysItem = findItem(qr.item, "bp-systolic")
    val systolic = sysItem?.answer?.firstOrNull()?.value?.asInteger()?.value

    val diaItem = findItem(qr.item, "bp-diastolic")
    val diastolic = diaItem?.answer?.firstOrNull()?.value?.asInteger()?.value

    val dangerItem = findItem(qr.item, "danger-signs")
    val dangerSigns = dangerItem?.answer?.mapNotNull {
      it.value?.asCoding()?.value?.display?.value
        ?: it.value?.asCoding()?.value?.code?.value
    } ?: emptyList()

    val notesItem = findItem(qr.item, "notes")
    val notes = notesItem?.answer?.firstOrNull()?.value?.asString()?.value?.value

    val encounterId = "anc-enc-${UUID.randomUUID()}"

    val encounterJson = JSONObject().apply {
      put("resourceType", "Encounter")
      put("id", encounterId)
      put("status", "finished")
      put("class", JSONObject().apply {
        put("system", "http://terminology.hl7.org/CodeSystem/v3-ActCode")
        put("code", "AMB")
        put("display", "ambulatory")
      })
      put("type", JSONArray().apply {
        put(JSONObject().apply { put("text", "Antenatal care contact") })
      })
      put("subject", JSONObject().apply {
        put("reference", "Patient/$patientId")
      })
      put("period", JSONObject().apply {
        put("start", visitDate)
        put("end", visitDate)
      })
    }.toString()

    val resourcesToCreate = mutableListOf<Resource>()
    val encounterResource = deserializeResource(encounterJson)
    resourcesToCreate.add(encounterResource)

    var weightJson: String? = null
    if (weight != null) {
      val weightObsId = "anc-obs-weight-${UUID.randomUUID()}"
      weightJson = JSONObject().apply {
        put("resourceType", "Observation")
        put("id", weightObsId)
        put("status", "final")
        put("category", JSONArray().apply {
          put(JSONObject().apply {
            put("coding", JSONArray().apply {
              put(JSONObject().apply {
                put("system", "http://terminology.hl7.org/CodeSystem/observation-category")
                put("code", "vital-signs")
                put("display", "Vital Signs")
              })
            })
          })
        })
        put("code", JSONObject().apply {
          put("coding", JSONArray().apply {
            put(JSONObject().apply {
              put("system", "http://loinc.org")
              put("code", "29463-7")
              put("display", "Body weight")
            })
          })
          put("text", "Body weight")
        })
        put("subject", JSONObject().apply { put("reference", "Patient/$patientId") })
        put("encounter", JSONObject().apply { put("reference", "Encounter/$encounterId") })
        put("effectiveDateTime", visitDate)
        put("valueQuantity", JSONObject().apply {
          put("value", weight)
          put("unit", "kg")
          put("system", "http://unitsofmeasure.org")
          put("code", "kg")
        })
      }.toString()
      resourcesToCreate.add(deserializeResource(weightJson))
    }

    var bpJson: String? = null
    if (systolic != null && diastolic != null) {
      val bpObsId = "anc-obs-bp-${UUID.randomUUID()}"
      bpJson = JSONObject().apply {
        put("resourceType", "Observation")
        put("id", bpObsId)
        put("status", "final")
        put("category", JSONArray().apply {
          put(JSONObject().apply {
            put("coding", JSONArray().apply {
              put(JSONObject().apply {
                put("system", "http://terminology.hl7.org/CodeSystem/observation-category")
                put("code", "vital-signs")
                put("display", "Vital Signs")
              })
            })
          })
        })
        put("code", JSONObject().apply {
          put("coding", JSONArray().apply {
            put(JSONObject().apply {
              put("system", "http://loinc.org")
              put("code", "85354-9")
              put("display", "Blood pressure panel with all children optional")
            })
          })
          put("text", "Blood pressure")
        })
        put("subject", JSONObject().apply { put("reference", "Patient/$patientId") })
        put("encounter", JSONObject().apply { put("reference", "Encounter/$encounterId") })
        put("effectiveDateTime", visitDate)
        put("component", JSONArray().apply {
          put(JSONObject().apply {
            put("code", JSONObject().apply {
              put("coding", JSONArray().apply {
                put(JSONObject().apply {
                  put("system", "http://loinc.org")
                  put("code", "8480-6")
                  put("display", "Systolic blood pressure")
                })
              })
            })
            put("valueQuantity", JSONObject().apply {
              put("value", systolic)
              put("unit", "mmHg")
              put("system", "http://unitsofmeasure.org")
              put("code", "mm[Hg]")
            })
          })
          put(JSONObject().apply {
            put("code", JSONObject().apply {
              put("coding", JSONArray().apply {
                put(JSONObject().apply {
                  put("system", "http://loinc.org")
                  put("code", "8462-4")
                  put("display", "Diastolic blood pressure")
                })
              })
            })
            put("valueQuantity", JSONObject().apply {
              put("value", diastolic)
              put("unit", "mmHg")
              put("system", "http://unitsofmeasure.org")
              put("code", "mm[Hg]")
            })
          })
        })
      }.toString()
      resourcesToCreate.add(deserializeResource(bpJson))
    }

    var gaJson: String? = null
    if (gaWeeks != null) {
      val gaObsId = "anc-obs-ga-${UUID.randomUUID()}"
      gaJson = JSONObject().apply {
        put("resourceType", "Observation")
        put("id", gaObsId)
        put("status", "final")
        put("code", JSONObject().apply {
          put("coding", JSONArray().apply {
            put(JSONObject().apply {
              put("system", "http://loinc.org")
              put("code", "18185-9")
              put("display", "Gestational age")
            })
          })
          put("text", "Gestational age")
        })
        put("subject", JSONObject().apply { put("reference", "Patient/$patientId") })
        put("encounter", JSONObject().apply { put("reference", "Encounter/$encounterId") })
        put("effectiveDateTime", visitDate)
        put("valueQuantity", JSONObject().apply {
          put("value", gaWeeks)
          put("unit", "wk")
          put("system", "http://unitsofmeasure.org")
          put("code", "wk")
        })
      }.toString()
      resourcesToCreate.add(deserializeResource(gaJson))
    }

    // QuestionnaireResponse
    val qrId = "anc-qr-${UUID.randomUUID()}"
    val qrRawJson = serializeResource(qr)
    val qrJsonObj = JSONObject(qrRawJson).apply {
      put("id", qrId)
      put("questionnaire", "http://example.org/fhir/Questionnaire/anc-contact")
      put("status", "completed")
      put("subject", JSONObject().apply { put("reference", "Patient/$patientId") })
      put("encounter", JSONObject().apply { put("reference", "Encounter/$encounterId") })
      put("authored", visitDate)
    }
    val qrFinalJson = qrJsonObj.toString()
    val qrResource = deserializeResource(qrFinalJson)
    resourcesToCreate.add(qrResource)

    // Persist locally in FHIR Engine Room database
    try {
      fhirEngine.create(*resourcesToCreate.toTypedArray())
      Log.d("AncRepository", "Created ${resourcesToCreate.size} resources in fhirEngine")
    } catch (e: Exception) {
      Log.e("AncRepository", "Error creating resources in fhirEngine", e)
    }

    // Persist remotely to FHIR server
    uploadResource("Encounter", encounterId, encounterJson)
    if (weightJson != null) {
      val wId = JSONObject(weightJson).getString("id")
      uploadResource("Observation", wId, weightJson)
    }
    if (bpJson != null) {
      val bId = JSONObject(bpJson).getString("id")
      uploadResource("Observation", bId, bpJson)
    }
    if (gaJson != null) {
      val gId = JSONObject(gaJson).getString("id")
      uploadResource("Observation", gId, gaJson)
    }
    uploadResource("QuestionnaireResponse", qrId, qrFinalJson)
  }

  private fun uploadResource(resourceType: String, id: String, json: String) {
    try {
      val url = URL("$serverBaseUrl/$resourceType/$id")
      val conn = url.openConnection() as HttpURLConnection
      conn.requestMethod = "PUT"
      conn.doOutput = true
      conn.setRequestProperty("Content-Type", "application/fhir+json")
      conn.outputStream.use { it.write(json.toByteArray(Charsets.UTF_8)) }
      val code = conn.responseCode
      Log.d("AncRepository", "Uploaded $resourceType/$id: responseCode=$code")
    } catch (e: Exception) {
      Log.e("AncRepository", "Failed to upload $resourceType/$id to server", e)
    }
  }

  private fun findItem(items: List<QuestionnaireResponse.Item>?, linkId: String): QuestionnaireResponse.Item? {
    if (items == null) return null
    for (item in items) {
      if (item.linkId.value == linkId) return item
      val found = findItem(item.item, linkId)
      if (found != null) return found
    }
    return null
  }

  private fun fetchUrl(urlStr: String): String? {
    return try {
      val url = URL(urlStr)
      val conn = url.openConnection() as HttpURLConnection
      conn.connectTimeout = 5000
      conn.readTimeout = 5000
      conn.requestMethod = "GET"
      conn.setRequestProperty("Accept", "application/fhir+json")
      if (conn.responseCode in 200..299) {
        conn.inputStream.bufferedReader().use { it.readText() }
      } else {
        Log.w("AncRepository", "HTTP error for $urlStr: ${conn.responseCode}")
        null
      }
    } catch (e: Exception) {
      Log.w("AncRepository", "Network fetch failed for $urlStr: ${e.message}")
      null
    }
  }

  private fun parseBundle(bundleJson: String): List<Resource> {
    val resources = mutableListOf<Resource>()
    try {
      val bundleObj = JSONObject(bundleJson)
      val entryArray = bundleObj.optJSONArray("entry") ?: return emptyList()
      for (i in 0 until entryArray.length()) {
        val entry = entryArray.getJSONObject(i)
        val resObj = entry.optJSONObject("resource")
        if (resObj != null) {
          val res = deserializeResource(resObj.toString())
          resources.add(res)
        }
      }
    } catch (e: Exception) {
      Log.e("AncRepository", "Error parsing bundle", e)
    }
    return resources
  }

