@Composable
fun VisitCard(visit: AncVisitItem) {
  Card(
    modifier = Modifier.fillMaxWidth(),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.surface
    )
  ) {
    Column(modifier = Modifier.padding(16.dp)) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
      ) {
        Text(
          text = "Visit Date: ${visit.date}",
          style = MaterialTheme.typography.titleMedium,
          fontWeight = FontWeight.Bold,
          color = MaterialTheme.colorScheme.primary
        )
        if (visit.gestationalAgeWeeks != null) {
          Box(
            modifier = Modifier
              .background(
                MaterialTheme.colorScheme.primaryContainer,
                RoundedCornerShape(8.dp)
              )
              .padding(horizontal = 8.dp, vertical = 4.dp)
          ) {
            Text(
              text = "${visit.gestationalAgeWeeks} wks",
              style = MaterialTheme.typography.labelMedium,
              color = MaterialTheme.colorScheme.onPrimaryContainer,
              fontWeight = FontWeight.SemiBold
            )
          }
        }
      }

      Spacer(modifier = Modifier.height(8.dp))
      HorizontalDivider(color = DividerDefaults.color.copy(alpha = 0.5f))
      Spacer(modifier = Modifier.height(8.dp))

      // Vitals grid
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween
      ) {
        Column(modifier = Modifier.weight(1f)) {
          Text(
            text = "Weight",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline
          )
          Text(
            text = if (visit.weight != null) "${visit.weight} kg" else "-",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.SemiBold
          )
        }

        Column(modifier = Modifier.weight(1f)) {
          Text(
            text = "Blood Pressure",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline
          )
          Text(
            text = if (visit.systolic != null && visit.diastolic != null) {
              "${visit.systolic}/${visit.diastolic} mmHg"
            } else "-",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.SemiBold
          )
        }

        Column(modifier = Modifier.weight(1f)) {
          Text(
            text = "Hemoglobin",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline
          )
          Text(
            text = if (visit.hemoglobin != null) "${visit.hemoglobin} g/dL" else "Not recorded",
            style = MaterialTheme.typography.bodyLarge,
            fontWeight = FontWeight.SemiBold
          )
        }
      }

      // Danger signs if any
      if (visit.dangerSigns.isNotEmpty()) {
        Spacer(modifier = Modifier.height(10.dp))
        val isDanger = visit.dangerSigns.any { !it.equals("none", ignoreCase = true) }
        val dangerText = visit.dangerSigns.joinToString(", ")
        Text(
          text = "Danger signs: $dangerText",
          style = MaterialTheme.typography.bodyMedium,
          color = if (isDanger) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.onSurface,
          fontWeight = if (isDanger) FontWeight.Bold else FontWeight.Normal
        )
      }

      // Notes if any
      if (!visit.notes.isNullOrBlank()) {
        Spacer(modifier = Modifier.height(6.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurfaceVariant
        )
      }
    }
  }
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import com.example.ancapp.data.AncVisitItem
import com.example.ancapp.data.PatientItem
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class AncViewModel(application: Application) : AndroidViewModel(application) {
  private val repository = AncRepository(application.applicationContext)

  private val _patients = MutableStateFlow<List<PatientItem>>(emptyList())
  val patients: StateFlow<List<PatientItem>> = _patients.asStateFlow()

  private val _selectedPatient = MutableStateFlow<PatientItem?>(null)
  val selectedPatient: StateFlow<PatientItem?> = _selectedPatient.asStateFlow()

  private val _visits = MutableStateFlow<List<AncVisitItem>>(emptyList())
  val visits: StateFlow<List<AncVisitItem>> = _visits.asStateFlow()

  private val _questionnaireJson = MutableStateFlow<String?>(null)
  val questionnaireJson: StateFlow<String?> = _questionnaireJson.asStateFlow()

  private val _isLoading = MutableStateFlow<Boolean>(false)
  val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

  init {
    loadInitialData()
  }

  fun loadInitialData() {
    viewModelScope.launch {
      _isLoading.value = true
      // First load local data if available
      loadLocalPatients()
      // Preload questionnaire JSON
      _questionnaireJson.value = repository.getQuestionnaireJson()
      // Sync with remote FHIR server
      repository.syncWithServer()
      // Reload local data post-sync
      loadLocalPatients()
      _isLoading.value = false
    }
  }

  fun refresh() {
    viewModelScope.launch {
      _isLoading.value = true
      repository.syncWithServer()
      loadLocalPatients()
      _selectedPatient.value?.let { current ->
        loadVisits(current.id)
      }
      _isLoading.value = false
    }
  }

  private suspend fun loadLocalPatients() {
    val patientList = repository.getPatients()
    _patients.value = patientList
    _selectedPatient.value?.let { current ->
      _selectedPatient.value = patientList.firstOrNull { it.id == current.id }
    }
  }

  fun selectPatient(patientId: String) {
    viewModelScope.launch {
      _selectedPatient.value = _patients.value.firstOrNull { it.id == patientId }
      loadVisits(patientId)
    }
  }

  fun loadVisits(patientId: String) {
    viewModelScope.launch {
      _visits.value = repository.getVisitsForPatient(patientId)
    }
  }

  fun saveVisit(patientId: String, qr: QuestionnaireResponse, onComplete: () -> Unit = {}) {
    viewModelScope.launch {
      _isLoading.value = true
      repository.saveVisit(patientId, qr)
      // Reload visits immediately
      _visits.value = repository.getVisitsForPatient(patientId)
      // Reload patients
      loadLocalPatients()
      _isLoading.value = false
      onComplete()
    }
  }
}

