import com.example.ancapp.ui.AncViewModel
import com.example.ancapp.ui.PatientDetailScreen
import com.example.ancapp.ui.RecordVisitScreen
import com.example.ancapp.ui.RegisterScreen

sealed class Screen {
  object Register : Screen()
  data class Detail(val patientId: String) : Screen()
  data class RecordVisit(val patientId: String) : Screen()
}

class MainActivity : ComponentActivity() {
  private val viewModel: AncViewModel by viewModels()

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        Surface(
          modifier = Modifier.fillMaxSize(),
          color = MaterialTheme.colorScheme.background
        ) {
          AncAppNavigation(viewModel)
        }
      }
    }
  }
}

@Composable
fun AncAppNavigation(viewModel: AncViewModel) {
  var currentScreen by remember { mutableStateOf<Screen>(Screen.Register) }

  val patients by viewModel.patients.collectAsState()
  val selectedPatient by viewModel.selectedPatient.collectAsState()
  val visits by viewModel.visits.collectAsState()
  val questionnaireJson by viewModel.questionnaireJson.collectAsState()
  val isLoading by viewModel.isLoading.collectAsState()

  when (val screen = currentScreen) {
    is Screen.Register -> {
      RegisterScreen(
        patients = patients,
        isLoading = isLoading,
        onRefresh = { viewModel.refresh() },
        onPatientClick = { patientId ->
          viewModel.selectPatient(patientId)
          currentScreen = Screen.Detail(patientId)
        }
      )
    }

    is Screen.Detail -> {
      BackHandler {
        currentScreen = Screen.Register
      }
      PatientDetailScreen(
        patient = selectedPatient,
        visits = visits,
        isLoading = isLoading,
        onRefresh = { viewModel.refresh() },
        onBack = { currentScreen = Screen.Register },
        onRecordVisitClick = {
          currentScreen = Screen.RecordVisit(screen.patientId)
        }
      )
    }

    is Screen.RecordVisit -> {
      BackHandler {
        currentScreen = Screen.Detail(screen.patientId)
      }
      RecordVisitScreen(
        patientName = selectedPatient?.name ?: "Patient",
        questionnaireJson = questionnaireJson,
        onSubmit = { qr ->
          viewModel.saveVisit(screen.patientId, qr) {
            currentScreen = Screen.Detail(screen.patientId)
          }
        },
        onCancel = {
          currentScreen = Screen.Detail(screen.patientId)
        }
      )
    }
  }
}

