private fun extractQuantityValue(obs: Observation?): Double? {
  if (obs == null) return null
  try {
    val jsonStr = json.encodeToString(Resource.serializer(), obs)
    val obj = JSONObject(jsonStr)
    if (obj.has("valueQuantity")) {
      val q = obj.getJSONObject("valueQuantity")
      if (q.has("value")) {
        return q.getDouble("value")
      }
    }
    if (obj.has("valueInteger")) {
      return obj.getInt("valueInteger").toDouble()
    }
  } catch (e: Exception) {
    android.util.Log.e("ANC_REPO", "Failed to extract quantity value", e)
  }
  return null
}

private fun extractBpValues(bpObs: Observation?): Pair<Int?, Int?> {
  if (bpObs == null) return Pair(null, null)
  var systolic: Int? = null
  var diastolic: Int? = null
  try {
    val jsonStr = json.encodeToString(Resource.serializer(), bpObs)
    val obj = JSONObject(jsonStr)
    val components = obj.optJSONArray("component")
    if (components != null) {
      for (i in 0 until components.length()) {
        val comp = components.getJSONObject(i)
        val codings = comp.optJSONObject("code")?.optJSONArray("coding")
        var code: String? = null
        if (codings != null) {
          for (j in 0 until codings.length()) {
            val c = codings.getJSONObject(j).optString("code")
            if (c.isNotEmpty()) {
              code = c
              break
            }
          }
        }
        val q = comp.optJSONObject("valueQuantity")
        val num = if (q != null && q.has("value")) q.optDouble("value").toInt() else null
        if (code == "8480-6") {
          systolic = num
        } else if (code == "8462-4") {
          diastolic = num
        }
      }
    }
  } catch (e: Exception) {
