private fun extractQrAnswers(qrJsonObj: JSONObject): Map<String, List<Any>> {
  val map = mutableMapOf<String, MutableList<Any>>()
  fun walk(itemArr: JSONArray?) {
    if (itemArr == null) return
    for (i in 0 until itemArr.length()) {
      val item = itemArr.optJSONObject(i) ?: continue
      val linkId = item.optString("linkId")
      val answers = item.optJSONArray("answer")
      if (linkId.isNotEmpty() && answers != null) {
        val list = map.getOrPut(linkId) { mutableListOf() }
        for (j in 0 until answers.length()) {
          val ans = answers.optJSONObject(j) ?: continue
          if (ans.has("valueDecimal")) list.add(ans.getDouble("valueDecimal"))
          else if (ans.has("valueInteger")) list.add(ans.getInt("valueInteger"))
          else if (ans.has("valueString")) list.add(ans.getString("valueString"))
          else if (ans.has("valueDate")) list.add(ans.getString("valueDate"))
          else if (ans.has("valueDateTime")) list.add(ans.getString("valueDateTime"))
          else if (ans.has("valueCoding")) {
            val c = ans.getJSONObject("valueCoding")
            val disp = c.optString("display")
            list.add(if (disp.isNotEmpty()) disp else c.optString("code"))
          }
        }
      }
      walk(item.optJSONArray("item"))
    }
  }
  walk(qrJsonObj.optJSONArray("item"))
  return map
}

